import type { Metadata } from "next";

/**
 * Open Graph / Twitter images – one place for every page.
 *
 * Next.js merges `metadata` shallowly: a page that defines its own
 * `openGraph` or `twitter` object replaces the one from the root layout,
 * including its images. Every page therefore wraps its metadata in
 * `withOgImage()`, which adds `og:image`, `og:image:alt` and `twitter:image`
 * unless the page already set images itself.
 */

export interface OgImage {
  url: string;
  width: number;
  height: number;
  alt: string;
}

/** Generated by app/opengraph-image.tsx (1200×630, logo on brand blue). */
export const DEFAULT_OG_IMAGE: OgImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Pomerico Group – BPO & HR Outsourcing Partner in Poland",
};

/**
 * Social share image of a blog post: a 1200×630 JPG crop of its featured
 * image, stored as /images/og/<featured image name>.jpg (see the image
 * standard in AGENTS.md).
 */
export function blogPostOgImage(post: {
  title: string;
  featuredImage: string;
  featuredImageAlt?: string;
}): OgImage {
  const name = post.featuredImage
    .split("/")
    .pop()!
    .replace(/\.[a-z0-9]+$/i, "");
  return {
    url: `/images/og/${name}.jpg`,
    width: 1200,
    height: 630,
    alt: post.featuredImageAlt ?? post.title,
  };
}

export function withOgImage(
  metadata: Metadata,
  image: OgImage = DEFAULT_OG_IMAGE
): Metadata {
  const openGraph = metadata.openGraph ?? {};
  const twitter = metadata.twitter ?? {};
  const fallbackTitle =
    typeof metadata.title === "string" ? metadata.title : undefined;
  const fallbackDescription = metadata.description ?? undefined;

  return {
    ...metadata,
    openGraph: {
      ...openGraph,
      images: openGraph.images ?? [image],
    },
    twitter: {
      card: "summary_large_image",
      title: (openGraph.title as string | undefined) ?? fallbackTitle,
      description: openGraph.description ?? fallbackDescription,
      ...twitter,
      images: twitter.images ?? [image],
    },
  };
}
